    'home.precision.title': 'Precision in Every Detail',
    'home.precision.subtitle': 'Our process is designed for clarity, speed, and excellence.',
    'home.precision.card1.header': 'Select & Estimate',
    'home.precision.card1.body': 'Choose your services and see an instant estimated cost based on your specific requirements.',
    'home.precision.card2.header': 'Visual Validation',
    'home.precision.card2.body': 'Upload photos, videos, or floor plans. Our system analyzes these specific site details to provide a 100% accurate quote.',
