    'services.title': 'Our Services',
    'services.learnMore': 'Learn More >',
    'services.endOfTenancy.title': 'End of Tenancy Cleaning',
    'services.endOfTenancy.description': '100% Deposit Return',
    'services.endOfTenancy.marketingDesc': 'We guarantee the full return of your deposit with our certified end-of-tenancy cleaning. We meticulously handle every corner of your home, from the inside of built-in appliances to windows, blinds, and specialized surfaces, ensuring the strictest standards required by property administrations in Zurich and Schaffhausen. For your convenience, we accept requests even with 48 hours notice. Once the work is completed, our management team conducts a thorough and documented quality control check, ensuring a stress-free transition and the full return of your security deposit.',
    'services.endOfTenancy.cta': 'Secure Deposit',
    'services.deepCleaning.title': 'Deep Cleaning',
    'services.deepCleaning.description': 'Instant Refresh',
    'services.deepCleaning.marketingDesc': 'Revitalize and refresh any space with our intensive deep cleaning service. It is the ideal option for seasonal renewals or for preparing a property for new occupants. We use professional equipment and techniques to tackle accumulated dirt, thoroughly descale kitchens and bathrooms, intensively clean grout, and treating specialized floors and upholstery. This service guarantees to bring your property to an exceptionally high level of hygiene and presentation, exceeding the requirements of a standard cleaning.',
    'services.deepCleaning.cta': 'Refresh Space',
    'services.dailyCleaning.title': 'Daily/Recurring Cleaning',
    'services.dailyCleaning.description': 'Spotless Every Day',
    'services.dailyCleaning.marketingDesc': 'Reliable and consistent cleaning maintenance for offices and residential properties. Our daily or weekly service ensures a continuously impeccable environment. We operate with full transparency and compliance with Swiss legislation: our staff is fully insured, and all mandatory social benefits (GAV, AHV, BVG) are included in our rate, offering you peace of mind and an ethical, consistent, and high-quality service.',
    'services.dailyCleaning.cta': 'Get Spotless',
    'services.movingFurniture.title': 'Furniture Moving',
    'services.movingFurniture.description': 'Stress-Free Moving',
    'services.movingFurniture.marketingDesc': 'Professional assistance for the safe movement and relocation of your furniture. Our team of experienced operators handles careful packing, loading, transportation, and efficient unloading at your new location, using specialized vehicles and equipment. We offer clear hourly rates based on the number of staff required, ensuring transparency and efficiency in time management. Our service includes comprehensive insurance coverage for all transported items.',
    'services.movingFurniture.cta': 'Move Easy',
    'services.propertyMaintenance.title': 'Property Maintenance',
    'services.propertyMaintenance.description': 'Quick Repairs',
    'services.propertyMaintenance.marketingDesc': 'Preventive and corrective solutions to keep your properties in optimal condition. We offer a rapid response service for any issue, from minor repairs to complex technical emergencies. We have a specialized in-house team capable of resolving critical problems such as gas leaks, electrical failures, plumbing issues, and professional rodent and pest control. We offer the efficiency of a single point of contact for all the technical needs of your home or building, avoiding the costly fees of external specialists.',
    'services.propertyMaintenance.cta': 'Quick Fix',
    'services.propertyManagement.title': 'Property Management',
    'services.propertyManagement.description': 'Total Peace of Mind',
    'services.propertyManagement.marketingDesc': 'Comprehensive and complete management of your real estate investment, handling the process from tenant search and contract management to financial administration and technical maintenance. Our service guarantees the optimization of your income and the peace mind of legal compliance. For total transparency and smooth communication, we are developing a web portal and a mobile application that will allow owners and tenants to access all property information, documents, and maintenance status in real time.',
    'services.propertyManagement.cta': 'Invest Smart',
    'services.additional.title': 'Additional Specialized Services',
    'services.additional.cta': 'Book a Free Consultation',
    'services.pest.title': 'Pest Control',
    'services.pest.desc': 'Professional, safe, and discreet solutions for all types of pest issues.',
    'services.waste.title': 'Waste Management',
    'services.waste.desc': 'Eco-friendly disposal, clearance, and recycling services for homes and offices.',
    'services.gutter.title': 'Gutter Cleaning',
    'services.gutter.desc': 'Essential maintenance to prevent water damage and ensure proper drainage.',
    'services.pricing.regular.title': 'Maintenance Cleaning (Regular)',
    'services.pricing.regular.rate': 'Recommended Rate: 43.50 CHF / hour (All Inclusive)',
    'services.pricing.regular.notes': 'Note: Requires a contract or subscription (Abo) with a minimum of 2.5 hours per visit, weekly or bi-weekly.',
    'services.pricing.deep.title': 'Deep Cleaning',
    'services.pricing.deep.rate': 'Recommended Rate: 55.00 - 58.00 CHF / hour (All Inclusive)',
    'services.pricing.deep.notes': 'Note: Unlike competitors (55 + VAT), our all-inclusive price is more transparent and easier for the client to understand.',
    'services.pricing.eot.title': 'End-of-Tenancy Cleaning (with Handover Guarantee)',
    'services.pricing.eot.notes': 'Note: Always indicate "Prices from..." (ab CHF) and that the final price is set after a brief, free, no-obligation inspection.',
    'services.pricing.eot.header.size': 'Property Size',
