    'services.pricing.maintenance.quote': 'By Quote (Offerte): For specific jobs (painting a room, repairing a leak), a detailed offer will be created.',
    'services.pricing.maintenance.specialist': 'Hourly Rate (Specialist): For hourly work (e.g., various repairs), the rate will be higher (e.g., 80 - 110 CHF / hour depending on the specialist).',
