    'sustainability.page.hero.title_line2': 'backed by real impact',
    'sustainability.page.hero.subtitle': 'We measure, verify, and improve the environmental impact of every operation.',
    'sustainability.page.hero.cta_story': 'VIEW OUR STORY',
    'sustainability.page.hero.badge_brochure': 'Brochure coming soon',
    'sustainability.page.floating.title': 'Building a cleaner future',
    'sustainability.page.floating.desc': 'through Swiss precision, circular logistics, and verified impact.',
    'sustainability.page.metrics.co2': 'CO2 emissions reduction',
