    'sustainability.page.pillars.p4.title': 'Social Impact',
    'sustainability.page.pillars.p4.desc': 'Active community programs and responsible employment.',
    'sustainability.page.bcorp.working_towards': 'WORKING TOWARDS',
    'sustainability.page.bcorp.title': 'On our path to B Corp certification',
    'sustainability.page.bcorp.desc': 'We are actively aligning our operations with B Corp certification standards, integrating environmental impact, social responsibility, and transparency criteria at every level of our work.',
    'sustainability.page.bcorp.check1': 'Ongoing internal impact audits',
    'sustainability.page.bcorp.check2': 'Supplier selection under sustainable criteria',
    'sustainability.page.bcorp.check3': 'Implementation of metrics and transparent reporting',
