    'sustainability.page.impact.compare_years': '2024 vs. 2022',
    'sustainability.page.roadmap.title': 'Reducing our environmental impact',
    'sustainability.page.roadmap.desc': 'We implement sustainable practices across all levels of our operation, from personnel selection to logistics optimization.',
    'sustainability.page.logistics.title': 'Low Emission Logistics',
    'sustainability.page.logistics.desc': 'Our procurement strategy is being designed to significantly lower carbon emissions by sourcing within the region.',
    'sustainability.page.logistics.stat1_badge': 'REDUCED TRUCK TRAVEL',
    'sustainability.page.logistics.stat1_impact': 'Impact: -30k',
    'sustainability.page.logistics.stat2_badge': 'AIS TRACKING OPTIMIZATION',
    'sustainability.page.logistics.alert': 'PRIORITIZING LOCAL PARTNERSHIPS FOR A FUTURE LOWER CARBON FOOTPRINT.',
    'sustainability.page.bento.circular.badge': 'CIRCULAR OPERATIONS',
    'sustainability.page.bento.circular.title': 'Circular Sustainability',
    'sustainability.page.bento.circular.desc': 'We will extend the life cycle of products and materials through reuse and responsible maintenance.',
    'sustainability.page.bento.people.badge': 'OUR PEOPLE',
    'sustainability.page.bento.people.title': 'Personnel Selection',
    'sustainability.page.bento.people.desc': 'Selecting personnel based on proximity to reduce commuting time.',
    'sustainability.page.bento.diversity.badge': 'OUR PEOPLE',
    'sustainability.page.bento.diversity.title': 'Diversity',
    'sustainability.page.bento.diversity.desc': 'We foster an inclusive environment where every individual is respected.',
    'sustainability.page.bento.diversity.tag': 'Inclusion',
    'sustainability.page.bento.partner.badge': 'PARTNERSHIP',
