    'gdpr.title': 'Privacy Policy & GDPR/nFADP Compliance',
    'gdpr.intro.title': 'Introduction',
    'gdpr.intro.p1': 'At Kraken Properties and Facilities Management ("Kraken"), we take your privacy seriously. This policy explains how we process personal data in accordance with the Swiss Federal Act on Data Protection (nFADP) and the EU General Data Protection Regulation (GDPR).',
    'gdpr.collect.title': 'Data We Collect & Purpose',
    'gdpr.collect.p1': 'We collect data to provide professional property services. This includes:',
    'gdpr.collect.item1': 'Identification Data: Name, address, email, and phone number (for service execution).',
    'gdpr.collect.item2': 'Property Data: Photos, videos, and square footage (for accurate quoting and validation).',
    'gdpr.collect.item3': 'Financial Data: We use PCI-DSS compliant third-party processors. Kraken does not store full credit card numbers on its own servers.',
    'gdpr.collect.item4': 'Technical Data: IP addresses and cookies (for website optimization).',
    'gdpr.basis.title': 'Legal Basis for Processing',
    'gdpr.basis.p1': 'We process your data based on:',
    'gdpr.basis.item1': 'Contractual Necessity: To provide the quotes and services you requested.',
    'gdpr.basis.item2': 'Legal Obligation: For tax and accounting purposes in Switzerland.',
    'gdpr.basis.item3': 'Legitimate Interest: To improve our service quality and ensure property security.',
    'gdpr.retention.title': 'Data Retention & Third Parties',
    'gdpr.retention.storage': 'Storage: Data is stored on secure servers, prioritizing Swiss or European locations.',
    'gdpr.retention.sharing': 'Sharing: We only share data with "Specialized Partners" (e.g., a plumber assigned to your job) or cloud service providers. We never sell your data.',
    'gdpr.retention.time': 'Retention: We keep client data for the duration of the business relationship and for 10 years thereafter (Swiss statutory requirement for accounting records).',
    'gdpr.rights.title': 'Your Rights',
    'gdpr.rights.p1': 'You have the right to access, correct, or delete your data. You may also withdraw consent for marketing at any time. To exercise these rights, contact kai@krakenpfm.ch.',
    'gdpr.disclaimer.main.title': 'Legal Disclaimer & Intellectual Property',
    'gdpr.disclaimer.estimates.title': 'Accuracy of Estimates',
    'gdpr.disclaimer.estimates.p1': 'The "Smart Booking" calculator provides non-binding estimates. A binding contract is only formed upon written confirmation and/or the provision of media (photos/videos) as per our T&Cs. Kraken reserves the right to adjust pricing based on actual on-site conditions.',
    'gdpr.disclaimer.liability.title': 'Limitation of Liability',
    'gdpr.disclaimer.liability.p1': 'While Kraken maintains a CHF 10 Million Liability Insurance, our digital liability is limited. We are not responsible for technical errors on the booking platform, damage caused by external links, or inaccurate information provided by the client.',
    'gdpr.disclaimer.ip.title': 'Intellectual Property (IP)',
    'gdpr.disclaimer.ip.p1': 'All content, including the Kraken mascot, logo, and "Smart Booking" logic, is the exclusive property of Kraken Properties and Facilities Management.',
    'gdpr.disclaimer.ip.usage': 'Usage: You may not copy, reproduce, or "frame" our website content for commercial purposes without written consent.',
    'gdpr.disclaimer.ip.trademarks': 'Trademarks: The name "Kraken" and its associated visual brand are protected under Swiss Trademark Law.',
