    'blog.readTime': 'Read Time',

    'blog.art1.title': 'End-of-Tenancy Cleaning in Zurich: Succeeding in Swiss Handover Inspections',
    'blog.art1.excerpt': 'Passing a property inspection in Switzerland is notoriously demanding. Learn the rigorous cleaning standards and legal guidelines required to get your full security deposit back.',
    'blog.art1.category': 'Residential Care',
    'blog.art1.p1': 'Moving out of a Swiss apartment comes with an infamous architectural milestone: the handover inspection (Wohnungsabgabe). In Switzerland, rental properties must be returned in close-to-immaculate condition, surpassing what many countries consider "deeply cleaned". Landlords or agencies inspect every millimeter with extreme attention to detail.',
    'blog.art1.p2': 'Common failure points during these handovers include lime-scale buildup in bathroom faucets, greasy ventilation filters in the kitchen, and overlooked storage rooms or cellars (Estrich/Keller). Utilizing a specialized cleaning service like Kraken—which offers a "Handover Guarantee" (Abgabegarantie)—ensures our deep-cleaning team is present to rectify any direct feedback from the inspector.',
    'blog.art1.p3': 'To succeed yourself, create a rigid checklist: descale all wet areas using professional-grade agents, clean window panes inside and out including the frames and blinds (Storen), vacuum and steam-clean parquet or carpeted floors, and ensure all wall plugs and woodwork are free of scuffs. Properly prepping saves thousands of Swiss Francs and ensures peace of mind.',

    'blog.art2.title': 'Alpine Solar Care: Elevating Output with Mountain Efficiency',
    'blog.art2.excerpt': 'Solar panels in Switzerland are exposed to unique high-altitude mountain pollen, industrial dust, and winter atmospheric soot. Discover why specialized pure-water washing is vital.',
    'blog.art2.category': 'Sustainability',
    'blog.art2.p1': 'Switzerland leads in clean energy integration, with thousands of photovoltaic installations gracing rooftops from Schaffhausen down to alpine valleys. However, many owners do not realize that dirt, bird droppings, Sahara dust, and pine pollen can degrade solar efficiency by up to 20% in a single season. The standard rain is rarely sufficient to clear this film.',
    'blog.art2.p2': 'Cleaning solar facilities is a delicate technical procedure. Traditional tap-water leaves mineral deposits (calcification) which can create micro-shades, heating up cells and permanently damaging them. Professional care requires demineralized pure water applied with soft, non-abrasive rotating brushes, avoiding any weight load on the delicate panels.',
    'blog.art2.p3': 'By performing regular solar maintenance, you protect your long-term capital investment and maximize the feed-in tariffs returned to the grid. In Switzerland, doing this twice a year—conceptually after the heavy spring pollen and preceding the first winter snowfall—maintains optimal performance and extends the lifespan of the system.',

    'blog.art3.title': 'AI & Data-Driven Facility Care: Redefining Swiss Workspaces',
    'blog.art3.excerpt': 'How IoT environmental sensors, smart scheduling, and centralized analytics are transforming workspace productivity and energy efficiency in modern Swiss offices.',
    'blog.art3.category': 'Innovation',
    'blog.art3.p1': 'Modern business infrastructure in Swiss hubs like Zurich, Winterthur, and Geneva is undergoing a massive digital overhaul. Traditional facility services rely on rigid, pre-set schedules (e.g., cleaning every desk at 18:00 daily). Today, smart buildings utilize active IoT sensors to trigger demand-based, responsive cleaning models.',
    'blog.art3.p2': 'By tracking actual room occupancy, air quality, and restroom usage, facilities teams focus energy and attention where it is truly needed. If a conference hall has been empty all day, the system automatically redirects technicians to high-traffic collaboration zones, optimizing workspace hygiene and operational efficiency.',
    'blog.art3.p3': 'In addition, centralized management allows business clients to monitor energy consumption, track technical service response times, and reduce corporate carbon footprints. Integrating smart tech is no longer just a luxury—it is the baseline for sustainable, highly productive commercial environments.',

