    // Navigation and Blog Keys
    'nav.blog': 'Blog',
    'blog.title': 'El Pulso del Orden',
    'blog.subtitle': 'Perspectivas profesionales sobre mantenimiento, pautas de entrega de viviendas y logística en Suiza.',
    'blog.readMore': 'Leer Artículo',
    'blog.backToBlog': 'Volver al Blog',
    'blog.published': 'Publicado el',
    'blog.author': 'Autor',
    'blog.readTime': 'Tiempo de lectura',

    'blog.art1.title': 'Limpieza de Fin de Alquiler en Zúrich: Guía Completa para la Entrega del Piso',
    'blog.art1.excerpt': 'Superar una inspección de entrega en Suiza es sumamente exigente. Descubre las rigurosas normas de limpieza y requisitos legales para asegurar la devolución de tu fianza.',
    'blog.art1.category': 'Mantenimiento Residencial',
    'blog.art1.p1': 'Mudarse de un apartamento en Suiza implica un hito sumamente exigente: la inspección de entrega (Wohnungsabgabe). En Suiza, las viviendas deben devolverse en un estado prácticamente impecable, superior a lo que comúnmente se considera limpieza profunda en otros países. Los propietarios o agencias inspeccionan cada rincón bajo lupa.',
    'blog.art1.p2': 'Los puntos más críticos que suelen fallar en estas entregas incluyen la acumulación de cal en las griferías, filtros de cocina grasientos y trasteros o sótanos (Estrich/Keller) sucios. Contratar un servicio profesional como Kraken, que ofrece una "Garantía de Entrega" (Abgabegarantie), asegura que nuestro equipo esté presente para resolver cualquier detalle señalado por el inspector.',
    'blog.art1.p3': 'Para tener éxito por tu cuenta, prepara un checklist estricto: descalcifica zonas húmedas con productos profesionales, limpia vidrios y marcos por ambos lados, limpia las persianas exteriores (Storen), aspira y limpia con vapor suelos de parqué o alfombras, y elimina cualquier marca de uso en las paredes. Prepararse correctamente evita multas y te da plena tranquilidad.',

    'blog.art2.title': 'Mantenimiento Solar en los Alpes: Maximizando la Energía',
    'blog.art2.excerpt': 'Los paneles solares en Suiza se exponen a polen de montaña, polvo sahariano y cenizas invernales. Entiende por qué la limpieza con agua pura es fundamental.',
    'blog.art2.category': 'Sostenibilidad',
    'blog.art2.p1': 'Suiza lidera la integración de energías limpias con miles de instalaciones fotovoltaicas en tejados desde Schaffhausen hasta los valles alpinos. Sin embargo, el polvo, los excrementos cosmopolitas, el polvo sahariano y el polen de pino pueden degradar el rendimiento solar hasta un 20% en una sola temporada. La lluvia habitual no basta para eliminar esta película.',
    'blog.art2.p2': 'La limpieza de instalaciones solares es un proceso técnico delicado. El agua corriente común deja residuos minerales (cal) que crean sombras térmicas locales, dañando permanentemente las células solares. El cuidado profesional requiere agua pura desmineralizada aplicada con cepillos giratorios suaves no abrasivos, sin ejercer peso sobre las placas.',
    'blog.art2.p3': 'Realizar un mantenimiento solar periódico protege tu inversión a largo plazo y maximiza la energía devuelta a la red eléctrica. En Suiza, realizarlo dos veces al año (tras el fuerte polen de primavera y antes de las primeras nevadas de invierno) ayuda a mantener el rendimiento óptimo de las células solares y alarga su vida útil.',

    'blog.art3.title': 'Tecnología e IoT en Oficinas: Redefiniendo el Espacio de Trabajo',
    'blog.art3.excerpt': 'Cómo los sensores ambientales de IoT, la planificación analítica y la gestión centralizada están transformando la eficiencia energética de las oficinas suizas modernas.',
    'blog.art3.category': 'Innovación',
    'blog.art3.p1': 'La infraestructura de oficinas en centros como Zúrich, Winterthur y Ginebra está viviendo una gran transformación digital. Los servicios tradicionales de mantenimiento dependen de horarios rígidos prefijados. Hoy en día, los edificios inteligentes utilizan sensores IoT activos para una limpieza basada en la demanda real.',
    'blog.art3.p2': 'Al monitorear la ocupación de salas, la calidad del aire y el uso de aseos, los equipos de mantenimiento dirigen sus esfuerzos exactamente donde es necesario. Si una sala ha estado vacía todo el día, el sistema redirige a los técnicos a zonas de alta interactividad, optimizando los recursos y la higiene.',
    'blog.art3.p3': 'Además, la gestión centralizada permite a los clientes corporativos monitorear el consumo de energía y reducir la huella de carbono operacional. Integrar tecnología inteligente ya no es un lujo, sino el estándar de los espacios comerciales altamente eficientes y sostenibles.',

