    // Mascot
    'mascot.home.1': 'Willkommen! Ich bin Kai. Ich bringe Ordnung ins Chaos, damit Sie die Ordnung geniessen können.',
    'mascot.home.2': 'Wussten Sie, dass Sie einen Service mit nur 48 Stunden Vorlauf buchen können?',
    'mascot.home.3': 'Von den Rheinfällen bis zu Ihrer Haustür – Schweizer Präzision ist mein zweiter Vorname!',
    'mascot.reminder.title': 'Unfertige Offerte!',
    'mascot.reminder.text': 'Sie haben Artikel in Ihrer Offerte. Vergessen Sie nicht, sie abzuschliessen!',
    'mascot.reminder.cta': 'Offerte abschliessen',
    'mascot.about.1': 'Möchten Sie meine Geschichte hören? Ich wurde bei den brausenden Rheinfällen in Schaffhausen geboren.',
    'mascot.about.2': 'Unser Team verfügt über mehr als 11 Jahre Erfahrung in der Spitzen-Hotellerie-Liegenschaftspflege. Wir sind Experten!',
    'mascot.about.3': 'Ich nutze meine Tentakel, um Ihre Räume perfekt zu ordnen und aufzuwerten!',
    'mascot.services.1': 'Entdecken Sie unsere Dienstleistungen für Wohnungen unten. Wir pflegen Ihre Immobilien meisterhaft!',
    'mascot.services.2': 'Umzug oder Tiefenreinigung geplant? Unsere Logistik ist auf Schnelligkeit und Präzision getrimmt.',
    'mascot.services.3': 'Klicken Sie auf eine Service-Karte, um zu sehen, wie wir architektonische Ordnung in Ihr Leben bringen.',
    'mascot.sustainability.1': 'Unser Engagement für den Planeten ist tief. Wir verwenden nur B-Corp-zertifizierte Produkte!',
    'mascot.sustainability.2': 'Unsere Website ist um 78% sauberer als der Durchschnitt des Internets. Sehen Sie sich unseren digitalen CO2-Bericht an!',
    'mascot.sustainability.3': 'Wir stellen lokale Mitarbeiter pro Bezirk ein, um Fahrtwege zu optimieren und CO2-Emissionen zu reduzieren.',
    'mascot.careers.1': 'Möchten Sie meiner Crew beitreten? Ich suche immer nach engagierten Fachkräften.',
    'mascot.careers.2': 'Wir zahlen über dem Branchendurchschnitt, weil zufriedene Mitarbeiter sich besser um Sie kümmern!',
    'mascot.careers.3': 'Erweitern Sie Ihre Tentakel mit uns! Bewerben Sie sich noch heute für eine Stelle in Zürich oder Schaffhausen.',
    'mascot.consultation.1': 'Bereit, Ihre Offerte zu erstellen? Wählen Sie einfach die Dienstleistungen aus, und ich übernehme die Rechnung!',
    'mascot.consultation.2': 'Laden Sie Fotos oder Pläne hoch! Das hilft mir, Ihnen einen absolut präzisen und transparenten Preis zu berechnen.',
    'mascot.consultation.3': 'Vergessen Sie nicht: Die Kombination mehrerer Haupt- und Spezialdienste schaltet eine KOSTENLOSE Lieferung frei!',
