    // Services Page Content translations (German)
    'services.endOfTenancy.title': 'Umzugsreinigung',
    'services.endOfTenancy.description': '100% Abgabegarantie',
    'services.endOfTenancy.marketingDesc': 'Wir garantieren die vollständige Rückerstattung Ihrer Kaution mit unserer zertifizierten Umzugsreinigung. Wir reinigen jeden Winkel Ihrer Wohnung akribisch, von den Einbaugeräten über die Fenster und Storen bis hin zu speziellen Oberflächen, entsprechend den strengen Vorgaben der Immobilienverwaltungen in Zürich und Schaffhausen. Auf Wunsch nehmen wir Aufträge auch mit einer Frist von 48 Stunden an. Nach Abschluss der Arbeiten führt unser Management eine gründliche Qualitätskontrolle durch, um eine stressfreie Übergabe zu gewährleisten.',
    'services.endOfTenancy.cta': 'Kaution sichern',

    'services.deepCleaning.title': 'Tiefenreinigung',
    'services.deepCleaning.description': 'Sofortige Frische',
    'services.deepCleaning.marketingDesc': 'Revitalisieren und erfrischen Sie jeden Raum mit unserer intensiven Tiefenreinigung. Ideal für den Frühlingsputz oder zur Vorbereitung einer Immobilie für neue Bewohner. Wir lösen hartnäckigen Schmutz, entkalken Küche und Bad gründlich, reinigen Fugen intensiv und behandeln spezielle Böden und Polster. Diese Dienstleistung bringt Ihre Immobilie auf ein ausserordentliches Hygiene- und Repräsentationsniveau, das weit über eine Standardreinigung hinausgeht.',
    'services.deepCleaning.cta': 'Raum erfrischen',

    'services.dailyCleaning.title': 'Unterhaltsreinigung',
    'services.dailyCleaning.description': 'Täglich makellos',
    'services.dailyCleaning.marketingDesc': 'Zuverlässige und regelmässige Unterhaltsreinigung für Büros und Wohnungen. Unser täglicher oder wöchentlicher Service sichert ein dauerhaft gepflegtes Umfeld. Wir arbeiten vollkommen transparent und gesetzeskonform: Alle Mitarbeitenden sind voll versichert, und Sozialleistungen (GAV, AHV, BVG) sind im Tarif inbegriffen – für Ihre Sicherheit und einen ethischen Service.',
    'services.dailyCleaning.cta': 'Regelmässiger Service',

    'services.movingFurniture.title': 'Umzug & Möbeltransport',
    'services.movingFurniture.description': 'Stressfreier Umzug',
    'services.movingFurniture.marketingDesc': 'Professionelle Hilfe für den sicheren Umzug und Transport Ihrer Möbel. Unser erfahrenes Team kümmert sich um das fachgerechte Verpacken, Beladen, den Transport und das speditive Entladen an Ihrem neuen Wohnort mit modernen Fahrzeugen. Wir bieten klare Stundensätze je nach Teamgrösse für volle Transparenz und Effizienz. All Ihre Transportgüter sind umfassend versichert.',
    'services.movingFurniture.cta': 'Einfacher Umzug',

    // Specialized Services
    'services.car.title': 'Fahrzeugaufbereitung',
    'services.car.subtitle': 'Mobiles Premium-Auto-Spa (Trockenreinigung)',
    'services.car.marketingDesc': 'Gönnen Sie Ihrem Fahrzeug ein Premium-Wellnesserlebnis, ohne Ihr Zuhause zu verlassen. Unsere mobile Fahrzeugaufbereitung nutzt professionelle Trockenreinigungstechniken, die eine erstklassige Tiefenreinigung des Innenraums und eine Aussenrestaurierung mit biologisch abbaubaren, wasserlosen und umweltfreundlichen B-Corp-zertifizierten Produkten ermöglichen. Von Fleckenentfernung über Alcantara-Pflege bis hin zum keramischen Lackschutz sorgen wir dafür, dass Ihr Auto bei minimaler Umweltbelastung wie neu aussieht und sich auch so anfühlt. Wir sind auf wasserlose Technologien spezialisiert, was Ihnen in Zürich und Schaffhausen ein absolut stressfreies Erlebnis garantiert.',

    'services.gardening.title': 'Gartenpflege',
    'services.gardening.desc': 'Fachgerechte Gartenpflege, Rasenpflege und Landschaftsgestaltung für alle Jahreszeiten.',
    'services.gardening.marketingDesc': 'Unser Gartenteam verbindet gärtnerisches Fachwissen mit Präzisionsgeräten, um Ihre Aussenbereiche zu verwandeln und zu pflegen. Von der saisonalen Bepflanzung über den präzisen Heckenschnitt bis hin zur organischen Düngung und Rasenrevitalisierung kümmern wir uns um alles. Wir setzen auf Biodiversität und nachhaltige Praktiken, damit Ihr Garten eine gesunde, lebendige Oase im Einklang mit der Schweizer Umwelt bleibt.',

    'services.exterior.title': 'Aussenreinigung',
    'services.exterior.desc': 'Professionelle Hochdruckreinigung und Fassadenrestaurierung für eine neuwertige Immobilie.',
    'services.exterior.marketingDesc': 'Bewahren Sie die strukturelle Integrität und den ästhetischen Wert Ihrer Immobilie mit unserer professionellen Aussenreinigung. Wir setzen spezialisierte Hochdruck- und Softwash-Verfahren ein, die auf verschiedene Materialien wie Naturstein, Beton, Holzterrassen und moderne Fassaden abgestimmt sind. Unser Prozess entfernt effektiv jahrelang abgelagerte Schadstoffe, Moos und Algen mit umweltschonenden Reinigungsmitteln, die sowohl Ihr Gebäude als auch das umliegende Ökosystem schützen.',

    'services.pest.title': 'Schädlingsbekämpfung',
    'services.pest.desc': 'Professionelle, sichere und diskrete Lösungen für Schädlingsprobleme aller Art.',
    'services.pest.marketingDesc': 'Kraken bietet schnelle und diskrete Hilfe bei der Schädlingsbekämpfung in Wohn- und Gewerbeimmobilien. Wir setzen auf moderne, schonende IPM-Strategien (Integrated Pest Management), die ungiftige Barrieren und die präventive Überwachung dem massiven Chemieeinsatz vorziehen. Ob saisonale Insektenbekämpfung oder akute Nagetierbekämpfung – unsere zertifizierten Techniker garantieren eine sichere, hygienische und gesetzeskonforme Umgebung für Sie und Ihre Mieter.',

    'services.waste.title': 'Entsorgung & Räumung',
    'services.waste.desc': 'Umweltfreundliche Entsorgung, Räumung und Recycling für Haushalt und Büro.',
    'services.waste.marketingDesc': 'Wir nehmen Ihnen die Last der Abfallentsorgung mit unserem umfassenden Sortier- und Entsorgungsservice ab. Kraken ist spezialisiert auf verantwortungsvolle Räumungen und übernimmt von Haushaltsgegenständen über Elektroschrott (WEEE) bis hin zu schweren Möbeln alles. Wir halten uns an höchste Schweizer Recyclingstandards und stellen sicher, dass jede Ladung fachgerecht sortiert und an zertifizierte regionale Recyclinghöfe geliefert wird, um die Umweltbelastung zu minimieren.',

    'services.gutter.title': 'Dachrinnenreinigung',
    'services.gutter.desc': 'Wichtige Wartung zur Vermeidung von Wasserschäden und zur Gewährleistung eines optimalen Abflusses.',
    'services.gutter.marketingDesc': 'Vernachlässigte Dachrinnen sind eine der Hauptursachen für strukturelle Wasserschäden und Fundamentprobleme. Unser Dachrinnen-Wartungsservice nutzt leistungsstarke Absaugsysteme und Inspektionskameras, um Ablagerungen gründlich zu entfernen und eine optimale Entwässerung zu gewährleisten. Wir reinigen nicht nur: Wir prüfen auf Verstopfungen, Undichtigkeiten und Gefälleprobleme, um Ihnen einen dokumentierten Zustandsbericht und Sicherheit bei den heftigen Schweizer Regenfällen zu bieten.',
    'services.window.title': 'Fensterreinigung',
    'services.window.desc': 'Streifenfreie Fenster-, Rahmen- und Glasreinigung für brillante Klarheit.',
    'services.window.marketingDesc': 'Geniessen Sie makellose Aussichten mit unserer professionellen Fensterreinigung. Unser erfahrenes Team reinigt nicht nur das Glas, sondern auch Rahmen, Fenstersimse und Storen für Privathaushalte und Gewerbe.',
    'services.upholstery.title': 'Polsterreinigung',
    'services.upholstery.desc': 'Tiefenreinigung und Pflege für alle Polster- und Ledermöbel sowie Teppiche.',
    'services.upholstery.marketingDesc': 'Bringen Sie die Frische in Ihre Polster zurück mit unserer professionellen Tiefenreinigung für Sofas, Sessel, Matratzen und Teppiche.',
    'services.restaurant.title': 'Bar- & Restaurantreinigung',
    'services.restaurant.desc': 'Spezialisierte Tiefenreinigung und Desinfektion für Küchen, Gasträume und Bar-Bereiche.',
    'services.restaurant.marketingDesc': 'Sichern Sie sich höchste Hygienestandards und die Einhaltung aller gesetzlichen Vorschriften mit unserer professionellen Gastronomie-, Bar- und Restaurantreinigung.',

