    // Navigation and Blog Keys
    'nav.blog': 'Blog',
    'blog.title': 'Der Puls der Ordnung',
    'blog.subtitle': 'Expertenperspektiven zu Facility Management, Richtlinien für die Wohnungsabgabe und Logistikoptimierung in der Schweiz.',
    'blog.readMore': 'Artikel lesen',
    'blog.backToBlog': 'Zurück zum Blog',
    'blog.published': 'Veröffentlicht am',
    'blog.author': 'Autor',
    'blog.readTime': 'Lesezeit',

    'blog.art1.title': 'Abgabereinigung in Zürich: So gelingt die perfekte Wohnungsübergabe',
    'blog.art1.excerpt': 'Die Wohnungsübergabe in der Schweiz ist berüchtigt für ihre strengen Anforderungen. Erfahren Sie, welche Reinigungsstandards und rechtlichen Richtlinien gelten, um Ihre Kaution vollständig zurückzuerhalten.',
    'blog.art1.category': 'Wohnen & Pflege',
    'blog.art1.p1': 'Der Auszug aus einer Schweizer Wohnung ist mit einem Meilenstein verbunden: der Wohnungsabgabe. In der Schweiz müssen Mietobjekte in fast makellosem Zustand zurückgegeben werden, der weit über das hinausgeht, was in anderen Ländern als "tiefengereinigt" gilt. Vermieter und Verwaltungen prüfen jeden Millimeter mit äusserster Sorgfalt.',
    'blog.art1.p2': 'Häufige Mängel bei der Abgabe sind Kalkrückstände an Armaturen, fettige Filter in Dunstabzugshauben sowie unzureichend gereinigte Nebenräume wie Estrich oder Keller. Ein professioneller Reinigungsservice wie Kraken mit "Abgabegarantie" stellt sicher, dass unser Team bei der Übergabe vor Ort ist, um direktes Feedback des Kontrolleurs sofort zu beheben.',
    'blog.art1.p3': 'Für die Selbstreinigung gilt: Entkalken Sie Nasszellen mit Profi-Mitteln, reinigen Sie Fensterscheiben samt Rahmen sowie die Storen, saugen und shampoonieren Sie Spannteppiche und befreien Sie Holzteile von Flecken. Eine gründliche Vorbereitung spart viel Geld und sorgt für eine entspannte Schlüsselübergabe.',

    'blog.art2.title': 'Alpine Solarzellen-Reinigung: Maximale Ausbeute auf dem Dach',
    'blog.art2.excerpt': 'Solaranlagen in der Schweiz sind alpinem Blütenstaub, Industriestaub und winterlicher Verschmutzung ausgesetzt. Erfahren Sie, warum die Reinigung mit Reinwasser unerlässlich ist.',
    'blog.art2.category': 'Nachhaltigkeit',
    'blog.art2.p1': 'Die Schweiz ist führend bei sauberer Energie, und Tausende von Photovoltaikanlagen zieren die Dächer von Schaffhausen bis in die Alpentäler. Viele Besitzer wissen jedoch nicht, dass Saharastaub, Vogelkot und Blütenstaub den Ertrag eines Solarsystems in nur einer Saison um bis zu 20 % mindern können. Normaler Regen reicht selten aus.',
    'blog.art2.p2': 'Die Solarreinigung ist ein technisch hochsensiber Prozess. Normales Leitungswasser hinterlässt Kalkflecken, die Hotspots erzeugen und die Zellen dauerhaft beschädigen können. Professionelle Pflege erfordert demineralisiertes Reinwasser und weiche Teleskopbürsten, ohne die empfindlichen Paneele mit Gewicht zu belasten.',
    'blog.art2.p3': 'Durch regelmässige Solarwartung schützen Sie Ihre Investition auf Jahrzehnte und maximieren die Einspeisevergütung. In der Schweiz empfiehlt sich die Reinigung zweimal im Jahr – idealerweise nach dem Pollenflug im Frühling und vor dem ersten Schneefall im Winter.',

    'blog.art3.title': 'IoT & Smart Facility Management: Schweizer Büros der Zukunft',
    'blog.art3.excerpt': 'Wie IoT-Umweltsensoren, datengesteuerte Routenplanung und zentrale Dashboards die Energieeffizienz und Arbeitsplatzproduktivität in modernen Schweizer Büros revolutionieren.',
    'blog.art3.category': 'Innovation',
    'blog.art3.p1': 'Die Büroinfrastruktur in Wirtschaftszentren wie Zürich und Winterthur erlebt eine digitale Revolution. Früher reinigte man nach starren Zeitplänen (z. B. jeden Tisch täglich um 18:00 Uhr). Heute setzen smarte Gebäude auf aktive IoT-Sensoren, um eine bedarfsgerechte, reaktive Reinigung zu steuern.',
    'blog.art3.p2': 'Durch die Erfassung von Raumbelegung, Luftqualität und Frequenz in den Sanitärräumen fokussieren sich die Serviceteams genau dort, wo Bedarf besteht. War ein Konferenzraum den ganzen Tag ungenutzt, leitet das System die Ressourcen automatisch in stark frequentierte Begegnungszonen um.',
    'blog.art3.p3': 'Diese digitalisierte Arbeitsweise verbessert nicht nur die Hygiene, sondern hilft Grosskunden auch beim Monitoring ihres ökologischen Fussabdrucks und der technischen Reaktionszeiten. Smart-FM ist kein Luxus mehr, sondern der moderne Standard für nachhaltige und effiziente Arbeitswelten.',

