    'mascot.reminder.cta': 'Finaliser le Devis',
    'mascot.about.1': 'Envie de connaître mes origines ? Je suis né dans les grondantes chutes du Rhin à Schaffhouse.',
    'mascot.about.2': 'Notre équipe a plus de 11 ans d’expérience en entretien de prestige. Nous sommes experts !',
