    'mascot.sustainability.3': 'Nous recrutons du personnel local pour réduire les émissions de transport. C’est la démarche verte Kraken.',
    'mascot.careers.1': 'Envie de rejoindre mon équipage ? Je recherche toujours des professionnels dévoués.',
    'mascot.careers.2': 'Nous payons au-dessus des standards de l’industrie car des employés heureux prennent mieux soin de vous !',
    'mascot.careers.3': 'Déployez vos tentacules avec nous ! Postulez dès aujourd’hui pour un poste à Zurich ou Schaffhouse.',
