    'servicesPage.process.step2.desc': 'Téléchargez des photos, des vidéos ou des plans. Notre équipe effectue une validation technique à distance.',
    'servicesPage.process.step3.title': '3. Confirmation de Prix Fixe',
    'servicesPage.process.step3.desc': 'Nous vérifions les données et vous envoyons une offre finale à prix fixe. Pas de surprise, pas d\'extra caché.',
    'servicesPage.process.step4.title': '4. Exécution Professionnelle',
    'servicesPage.process.step4.desc': 'Votre équipe Kraken dédiée arrive à l\'heure avec un équipement complet pour une exécution de précision suisse.',

    // CTA Box (French)
    'servicesPage.ctabox.title': 'Première Consultation Gratuite',
    'servicesPage.ctabox.subtitle': 'Aucun engagement. Que de la clarté.',
    'servicesPage.ctabox.desc': 'Obtenez votre devis personnalisé pour Schaffhouse, Zurich ou Winterthour — en quelques minutes.',
    'servicesPage.ctabox.btn': 'Démarrer le devis',
    'servicesPage.ctabox.call': 'Ou appelez le : +41 77 450 57 05',

    // CTA Footer (French)
    'servicesPage.ctafooter.title1': 'Qualité Suisse.',
    'servicesPage.ctafooter.title2': 'Garantie.',
    'servicesPage.ctafooter.desc': 'Du nettoyage de fin de bais à la gestion globale des installations — Kraken est votre partenaire de confiance à Schaffhouse, Zurich et Winterthour.',
    'servicesPage.ctafooter.btn1': 'Devis Gratuit',
    'servicesPage.ctafooter.btn2': 'Clients Entreprise →',
    'servicesPage.pricing.abo': 'Abo / Souss.',
