    // Services Page Content translations (French)
    'services.endOfTenancy.title': 'Nettoyage de Fin de Bail',
    'services.endOfTenancy.description': 'Garantie de Remise 100%',
    'services.endOfTenancy.marketingDesc': 'Nous garantissons la restitution intégrale de votre caution grâce à notre nettoyage certifié de fin de bail. Nous traitons méticuleusement chaque recoin de votre logement, de l\'intérieur des appareils encastrés aux fenêtres, stores et surfaces spéciales, en respectant les normes les plus strictes exigées par les gérances à Zurich et Schaffhouse. Pour votre confort, nous acceptons les demandes même avec un préavis de 48 heures. Une fois le travail terminé, notre équipe procède à un contrôle de qualité approfondi, garantissant une transition sans stress et l\'obtention de votre remboursement de caution.',
    'services.endOfTenancy.cta': 'Garantir la Caution',

    'services.deepCleaning.title': 'Nettoyage en Profondeur',
    'services.deepCleaning.description': 'Rafraîchissement Immédiat',
    'services.deepCleaning.marketingDesc': 'Revitalisez et rafraîchissez n\'importe quel espace grâce à notre service de nettoyage en profondeur intensif. Option idéale pour un grand ménage saisonnier ou pour préparer un bien à de nouveaux occupants. Nous utilisons des équipements et des techniques professionnels pour éliminer la saleté accumulée, détartrer profondément les cuisines et salles de bain, nettoyer intensément les joints et traiter les sols spéciaux et tissus d\'ameublement. Ce service amène votre propriété à un niveau exceptionnel d\'hygiène et de présentation, bien supérieur à un nettoyage classique.',
    'services.deepCleaning.cta': 'Rafraîchir l\'Espace',

    'services.dailyCleaning.title': 'Nettoyage Quotidien/Régulier',
    'services.dailyCleaning.description': 'Impeccable Tous les Jours',
    'services.dailyCleaning.marketingDesc': 'Entretien de nettoyage fiable et régulier pour bureaux et résidences privées. Notre service quotidien ou hebdomadaire garantit des espaces toujours impeccables. Nous opérons en toute transparence et conformité avec la loi suisse : notre personnel est pleinement assuré, et toutes les cotisations sociales obligatoires (CCT, AVS, LPP) sont incluses dans nos tarifs, vous apportant tranquillité et un service éthique et de qualité supérieure.',
    'services.dailyCleaning.cta': 'Ménage Régulier',

    'services.movingFurniture.title': 'Déménagement & Transport',
    'services.movingFurniture.description': 'Déménagement Sans Stress',
    'services.movingFurniture.marketingDesc': 'Assistance professionnelle para le transport et le déménagement sécurisé de votre mobilier. Notre équipe d\'opérateurs expérimentés prend en charge l\'emballage minutieux, le chargement, le transport et le déchargement efficace dans votre nouveau logement, avec des véhicules et outils spécialisés. Nous proposons des tarifs horaires transparents selon le nombre d\'employés requis. Tous vos biens sont couverts par une assurance complète pendant le transport.',
    'services.movingFurniture.cta': 'Déménager Facile',

    // Specialized Services
    'services.car.title': 'Esthétique Automobile',
    'services.car.subtitle': 'Spa Auto Mobile Professionnel (Nettoyage à Sec)',
    'services.car.marketingDesc': 'Offrez à votre véhicule une expérience de spa premium sans quitter votre domicile. Notre service d\'esthétique automobile mobile utilise des techniques professionnelles de nettoyage à sec, offrant un nettoyage intérieur en profondeur de haut niveau et une restauration extérieure à l\'aide de produits écologiques, sans eau et biodégradables certifiés B Corp. De l\'élimination des taches et du traitement de l\'Alcantara à la protection par traitement céramique, nous veillons à ce que votre voiture retrouve son aspect et son toucher d\'origine avec un impact environnemental minimal. Nous sommes spécialisés dans les technologies sans eau pour une expérience sans souci à Zurich et Schaffhouse.',

    'services.gardening.title': 'Jardinage & Espaces Verts',
    'services.gardening.desc': 'Entretien professionnel de jardins, soin de la pelouse et aménagement paysager en toutes saisons.',
    'services.gardening.marketingDesc': 'Notre équipe de jardiniers associe expertise horticole et équipements de précision pour transformer et entretenir vos espaces extérieurs. De la plantation saisonnière au traitement des haies de précision en passant par la fertilisation organique et la revitalisation de la pelouse, nous gérons tout. Nous privilégions la biodiversité et les pratiques durables afin que votre jardin reste un espace de vie sain, actif et dynamique, en parfaite harmonie avec l\'écosystème suisse.',

    'services.exterior.title': 'Nettoyage Extérieur',
    'services.exterior.desc': 'Lavage haute pression professionnel et traitement des façades pour une propriété comme neuve.',
    'services.exterior.marketingDesc': 'Préservez l\'intégrité structurelle et la valeur esthétique de votre bien avec notre nettoyage extérieur professionnel de qualité industrielle. Nous utilisons des techniques de haute pression et de nettoyage doux adaptées aux différents supports, notamment la pierre naturelle, le béton, les terrasses en bois et les façades modernes. Notre processus élimine efficacement la saleté, la mousse et les algues, en utilisant des détergents respectueux de l\'environnement.',

    'services.pest.title': 'Contrôle des Nuisibles',
    'services.pest.desc': 'Solutions professionnelles, sûres et discrètes contre tous types de nuisibles.',
    'services.pest.marketingDesc': 'Kraken propose une intervention rapide et discrète pour le contrôle des nuisibles dans les propriétés résidentielles et commerciales. Nous privilégions les stratégies modernes de lutte intégrée (IPM) à faible impact environnemental, favorisant des barrières non toxiques et un suivi préventif plutôt que l\'usage intensif de produits chimiques. Nos techniciens certifiés garantissent un environnement sain, hygiénique et conforme aux normes en vigueur pour vous et vos locataires.',

    'services.waste.title': 'Gestion des Déchets',
    'services.waste.desc': 'Évacuation, débarras et recyclage écoresponsables pour habitations et bureaux.',
    'services.waste.marketingDesc': 'Nous vous soulageons de la gestion de vos déchets grâce à notre service complet de tri et d\'évacuation. Kraken est spécialisé dans le débarras écoresponsable, prenant en charge tout type de biens, du mobilier encombrant aux équipements électriques et électroniques (DEEE). Nous appliquons rigoureusement les normes de recyclage suisses et garantissons l\'acheminement vers des centres de traitements régionaux agréés afin de réduire l\'empreinte écologique.',

    'services.gutter.title': 'Nettoyage de Gouttières',
    'services.gutter.desc': 'Entretien essentiel pour éviter les infiltrations d\'eau et assurer une bonne évacuation.',
    'services.gutter.marketingDesc': 'Des gouttières négligées sont une cause majeure de dommages structurels et d\'infiltrations. Notre service d\'entretien utilise des systèmes d\'aspiration à haute performance et des caméras d\'inspection pour éliminer efficacement tous les débris. Nous nettoyons et inspectons les fixations, les joints et l\'écoulement, en vous fournissant un rapport complet pour votre sérénité lors des fortes pluies suisses.',

