    'servicesPage.process.title1': 'È così semplice.',
    'servicesPage.process.title2': 'Chiaro. Preciso. Rapido.',
    'servicesPage.process.desc': 'Abbiamo riprogettato il processo di prenotazione — per una trasparenza totale e prezzi precisi al 100%, prima di accedere alla tua proprietà.',
