    // Services Page Content translations (Italian)
    'services.endOfTenancy.title': 'Pulizia di Fine Locazione',
    'services.endOfTenancy.description': 'Garanzia Restituzione Deposito 100%',
    'services.endOfTenancy.marketingDesc': 'Garantiamo la restituzione completa del vostro deposito con la nostra pulizia certificata di fine locazione. Gestiamo meticolosamente ogni angolo della vostra casa, dall\'interno degli elettrodomestici da incasso a finestre, tapparelle e superfici speciali, garantendo i più severi standard richiesti dalle amministrazioni immobiliari di Zurigo e Sciaffusa. Per vostra comodità, accettiamo richieste anche con 48 ore di preavviso. Una volta ultimato il lavoro, il nostro team di gestione esegue un controllo di qualità approfondito e documentato, garantendo una transizione senza stress e la restituzione completa del deposito cauzionale.',
    'services.endOfTenancy.cta': 'Assicura Deposito',

    'services.deepCleaning.title': 'Pulizia Profonda',
    'services.deepCleaning.description': 'Rinfresco Istantaneo',
    'services.deepCleaning.marketingDesc': 'Rivitalizza e rinfresca qualsiasi spazio con il nostro servizio di pulizia profonda intensiva. È l\'opzione ideale per rinnovi stagionali o per preparare un immobile per i nuovi occupanti. Utilizziamo attrezzature e tecniche professionali per affrontare lo sporco accumulato, disincrostare a fondo cucine e bagni, pulire intensamente le fughe e trattare pavimenti e tappezzeria specializzati. Questo servizio garantisce di portare la vostra proprietà a un livello eccezionalmente alto di igiene e presentazione, superando i requisiti di una pulizia standard.',
    'services.deepCleaning.cta': 'Rinfresca Spazio',

    'services.dailyCleaning.title': 'Pulizia Giornaliera/Ricorrente',
    'services.dailyCleaning.description': 'Impeccabile ogni giorno',
    'services.dailyCleaning.marketingDesc': 'Pulizia affidabile e costante per uffici e proprietà residenziali. Il nostro servizio giornaliero o settimanale garantisce un ambiente continuamente impeccabile. Operamos nel pieno rispetto delle norme svizzere: il nostro personale è interamente assicurato e tutti i contributi sociali obbligatori (GAV, AHV, BVG) sono inclusi nella nostra tariffa, offrendoti massima tranquillità e un servizio etico, coerente e di alta qualità.',
    'services.dailyCleaning.cta': 'Servizio Regolare',

    'services.movingFurniture.title': 'Trasloco & Trasporto Mobili',
    'services.movingFurniture.description': 'Traslochi Senza Stress',
    'services.movingFurniture.marketingDesc': 'Assistenza professionale per la movimentazione e il trasferimento dei tuoi mobili in totale sicurezza. Il nostro team di operatori esperti si occupa con cura dell\'imballaggio, carico, trasporto e scarico efficiente nella nuova sede, utilizzando veicoli e attrezzature specializzati. Offriamo tariffe orarie chiare basate sul numero di personale richiesto, garantendo trasparenza ed efficienza. Il servizio include una copertura assicurativa completa per tutti i beni trasportati.',
    'services.movingFurniture.cta': 'Trasloco Facile',

    // Specialized Services
    'services.car.title': 'Car Detailing',
    'services.car.subtitle': 'Spa Mobile Professionale (Lavaggio a Secco)',
    'services.car.marketingDesc': 'Regala al tuo veicolo un esperienza di benessere premium senza muoverti da casa. Il nostro servizio di car detailing a domicilio utilizza tecniche professionali "a secco" per una pulizia interna profonda d alta gamma e una cura dettagliata degli esterni, impiegando prodotti ecologici certificati B Corp senza consumo d acqua. Dalla rimozione di macchie difficili al trattamento Alcantara e protezione ceramica, restituiamo al tuo veicolo l aspetto di un auto nuova riducendo al minimo l impatto ambientale. Siamo specialisti nelle tecnologie ecosostenibili senz acqua a Zurigo e Sciaffusa.',

    'services.gardening.title': 'Giardinaggio',
    'services.gardening.desc': 'Manutenzione esperta del giardino, cura del prato e servizi di paesaggistica per tutte le stagioni.',
    'services.gardening.marketingDesc': 'Il nostro team di giardinieri specializzati unisce competenze botaniche e attrezzature di precisione per trasformare e curare i tuoi spazi verdi esterni. Dalla piantumazione stagionale alla potatura di siepi e rami, fino alla concimazione naturale e rigenerazione del prato. Promuoviamo la biodiversità e ottimizziamo l irrigazione nel rispetto dell ambiente svizzero.',

    'services.exterior.title': 'Pulizia Esterni',
    'services.exterior.desc': 'Lavaggio idropulitrice professionale e restauro facciate per esterni come nuovi.',
    'services.exterior.marketingDesc': 'Preserva il valore estetico e strutturale del tuo immobile con la nostra pulizia professionale per esterni. Utilizziamo tecniche dedicate ad alta pressione o lavaggio soft per proteggere materiali porosi o delicati come pietra naturale, cemento, legno e facciate metalliche. Rimuoviamo muffe, alghe e sporco atmosferico accumulato con detergenti eco-compatibili.',

    'services.pest.title': 'Disinfestazione',
    'services.pest.desc': 'Soluzioni professionali, sicure e discrete per tutti i problemi di parassiti.',
    'services.pest.marketingDesc': 'Kraken offre interventi rapidi e discreti per il controllo di insetti e infestanti in uffici e abitazioni private. Scegliamo tecniche a basso impatto che privilegiano sistemi di barriere ecologiche e monitoraggio preventivo. I nostri tecnici svizzeri qualificati garantiscono la massima sicurezza ed igiene degli ambienti abitativi.',

    'services.waste.title': 'Smaltimento & Sgomberi',
    'services.waste.desc': 'Sgomberi parziali o totali, ritiro rifiuti ingombranti e riciclaggio etico.',
    'services.waste.marketingDesc': 'Rendiamo semplice e organizzato lo sgombero di uffici, cantine o interi appartamenti. Kraken gestisce con professionalità la separazione dei materiali e il riciclaggio dei rifiuti elettronici (RAEE/WEEE) o arredi pesanti. Consegniamo ogni carico a centri svizzeri regionali di recupero autorizzati nel massimo rispetto ecologico.',

    'services.gutter.title': 'Pulizia Grondaie',
    'services.gutter.desc': 'Manutenzione preventiva per scongiurare infiltrazioni d acqua e garantire il corretto drenaggio.',
    'services.gutter.marketingDesc': 'Grondaie ostruite causano infiltrazioni pericolose sulle pareti e alle fondamenta. Il nostro servizio utilizza sistemi di aspirazione telescopici ad alta potenza e telecamere di monitoraggio per ripulire perfettamente rami, foglie e sedimenti prima dell arrivo delle piogge, certificando la corretta pendenza.',

