    'payment.bypass.title': 'Simula pagamento Sandbox (Consigliato)',
    'payment.bypass.desc': 'Simula una conferma di pagamento istantanea. Questo attiverà i webhook (Make.com), genererà ricevute finali e invierà e-mail di conferma. Perfetto per visualizzare in anteprima il ciclo completo de prenotazione.',
