    // Navigation and Blog Keys
    'nav.blog': 'Blog',
    'blog.title': 'Il Battito dell\'Ordine',
    'blog.subtitle': 'Analisi professionali su facility management, riconsegna appartamenti e ottimizzazione della logistica in Svizzera.',
    'blog.readMore': 'Leggi l\'Articolo',
    'blog.backToBlog': 'Torna al Blog',
    'blog.published': 'Pubblicato il',
    'blog.author': 'Autore',
    'blog.readTime': 'Tempo di lettura',

    'blog.art1.title': 'Pulizia di Fine Locazione a Zurigo: Guida alla Riconsegna dell\'Appartamento',
    'blog.art1.excerpt': 'Riconsegnare una casa in locazione in Svizzera é notoriamente impegnativo. Scopri gli standard di pulizia richiesti e le norme legali per ottenere il rimborso totale della cauzione.',
    'blog.art1.category': 'Manutenzione Residenziale',
    'blog.art1.p1': 'Il trasloco da un appartamento svizzero comporta un appuntamento cruciale: il controllo di riconsegna (Wohnungsabgabe). In Svizzera, le proprietà devono essere restituite in condizioni quasi immacolate, superando di gran lunga gli standard di altri paesi. Proprietari e agenzie esaminano ogni dettaglio.',
    'blog.art1.p2': 'I punti di fallimento frequenti includono il calcare sui rubinetti, i filtri della cucina saturi di grasso e cantine (Keller) o solai non spazzati. Scegliere un partner specializzato come Kraken, con la sua formula di "Garanzia di Consegna" (Abgabegarantie), garantisce la presenza del nostro team per risolvere subito qualsiasi obiezione.',
    'blog.art1.p3': 'Per pulire da soli, seguite un elenco rigoroso: decalcificate i bagni con detergenti professionali, pulite i vetri e i telai delle finestre su entrambi i lati, pulite le tapparelle esterne (Storen), igienizzate i pavimenti ed eliminate i graffi dal legno. Prepararsi al meglio evita costose trattenute e assicura tranquillità.',

    'blog.art2.title': 'Manutenzione Pannelli Solari Alpini: Massima Efficienza Energetica',
    'blog.art2.excerpt': 'I pannelli solari in Svizzera offrono prestazioni eccellenti ma risentono di polline montano, sabbia del Sahara e fuliggine invernale. Scopri perché la pulizia professionale con agua pura é essenziale.',
    'blog.art2.category': 'Sostenibilità',
    'blog.art2.p1': 'La Svizzera è leader nell’energia solare, con migliaia di impianti installati da Sciaffusa fino alle valli alpine. Tuttavia, sporco, deiezioni di uccelli, polveri e pollini possono ridurre il rendimento dei pannelli solari fino al 20% in una sola stagione. La pioggia non basta a pulire questa barriera sottile.',
    'blog.art2.p2': 'La pulizia dei moduli fotovoltaici é un’operazione tecnica delicata. L’acqua del rubinetto lascia depositi calcarei che creano micro-ombre termiche, surriscaldando e danneggiando le celle. Un intervento professionale richiede acqua pura demineralizzata e spazzole rotanti delicate, senza caricare pesi sulle strutture.',
    'blog.art2.p3': 'Un programma di pulizia programmato, preferibilmente in primavera dopo l’impollinazione e in autunno prima delle nevicate, protegge il valore degli impianti tecnologici nel tempo e assicura la massima produzione di energia green.',

    'blog.art3.title': 'IoT e Smart Facility Office: Il Futuro degli Uffici Svizzeri',
    'blog.art3.excerpt': 'Come sensori ambientali IoT, pianificazione predittiva e dashboard unificate stanno ottimizzando il benessere dei collaboratori e i consumi energetici.',
    'blog.art3.category': 'Innovazione',
    'blog.art3.p1': 'Negli uffici di Zurigo, Winterthur e Ginevra si sta compiendo una vera rivoluzione digitale. Le pulizie tradizionali seguono orari rigidi di calendario. Oggi invece, gli edifici intelligenti utilizzano sensori IoT attivi per attivare le pulizie in tempo reale secondo l’effettivo utilizzo.',
    'blog.art3.p2': 'Tracciando l’occupazione delle sale riunioni, la qualidade dell’aria e la frequenza nei servizi igienici, le squadre intervengono tempestivamente dove serve davvero. Se una sala é rimasta vuota, gli operatori possono concentrarsi sulle aree break e sui tavoli di co-working più caldi.',
    'blog.art3.p3': 'La gestione basata sui dati consente ai clienti aziendali di monitorare i consumi energetici e valutare l’impatto ambientale e le tempistiche di risposta tecnica. Una manutenzione smart non é più solo un accessorio, ma il pilastro per uffici moderni, efficienti e sani.',

