    'servicesPage.process.title1': 'Assim de fácil.',
    'servicesPage.process.title2': 'Claro. Preciso. Rápido.',
    'servicesPage.process.desc': 'Nós redesenhamos o processo de reserva — para total transparência e preços 100% corretos antes de entrarmos no seu imóvel.',
    'servicesPage.process.step1.title': '1. Configurar escopo',
    'servicesPage.process.step1.desc': 'Escolha os seus serviços e utilize o nosso calculador inteligente de orçamento para uma estimativa imediata de acordo com as normas da indústria suíça.',
