    // CTA Footer (Portuguese)
    'servicesPage.ctafooter.title1': 'Qualidade Suíça.',
    'servicesPage.ctafooter.title2': 'Garantida.',
    'servicesPage.ctafooter.desc': 'Desde a limpeza de final de contrato à gestão integral de instalações — a Kraken é o seu parceiro de confiança em Schaffhausen, Zurique e Winterthur.',
    'servicesPage.ctafooter.btn1': 'Orçamento Grátis',
