    'servicesPage.pricing.abo': 'Abo / Subsc.',
    'servicesPage.trust.certified': 'Certificado Suíço',

    // Services Page Content translations (Portuguese)
    'services.endOfTenancy.title': 'Limpeza de Fim de Contrato',
    'services.endOfTenancy.description': 'Retorno de Depósito 100%',
    'services.endOfTenancy.marketingDesc': 'Garantizamos a devolução total do seu depósito com a nossa limpeza de fim de contrato certificada. Limpamos meticulosamente cada canto da sua casa, desde o interior dos eletrodomésticos embutidos até janelas, persianas e superfícies especializadas, assegurando as normas mais rigorosas exigidas pelas administrações imobiliárias em Zurique e Schaffhausen. Para sua comodidade, aceitamos pedidos com aviso prévio de até 48 horas. Concluído o trabalho, a nossa equipa de gestão realiza um controlo de qualidade minucioso e documentado, garantindo uma transição sem stress e a devolução total do seu depósito de segurança.',
    'services.endOfTenancy.cta': 'Garantir Depósito',

    'services.deepCleaning.title': 'Limpeza Profunda',
    'services.deepCleaning.description': 'Renovação Imediata',
    'services.deepCleaning.marketingDesc': 'Revitalize e refresque qualquer espaço com o nosso serviço de limpeza profunda intensiva. É a opção ideal para renovações sazonais ou para preparar o imóvel para novos ocupantes. Utilizamos equipamentos e técnicas profissionais para combater a sujidade acumulada, descalcificar profundamente cozinhas e casas de banho, limpar minuciosamente as juntas e tratar pisos especiais e estofos. Este serviço garante trazer à sua propriedade um nível excecional de higiene e apresentação, superando as exigências de uma limpeza padrão.',
    'services.deepCleaning.cta': 'Renovar Espaço',

    'services.dailyCleaning.title': 'Limpeza Diaria/Recorrente',
    'services.dailyCleaning.description': 'Impecável Todos os Dias',
    'services.dailyCleaning.marketingDesc': 'Limpeza de manutenção fiável e regular para escritórios e propriedades residenciais. O nosso serviço diário ou semanal garante um ambiente continuamente impecável. Operamos com transparência e total conformidade com a legislação suíça: o nosso pessoal está totalmente seguro e todos os benefícios sociais obrigatórios (GAV, AHV, BVG) estão incluídos na nossa tarifa, oferecendo-lhe tranquilidade e um serviço ético, consistente e de alta qualidade.',
    'services.dailyCleaning.cta': 'Mantenimento Regular',

    'services.movingFurniture.title': 'Mudança de Móveis',
    'services.movingFurniture.description': 'Mudanças Sem Stress',
    'services.movingFurniture.marketingDesc': 'Assistência profissional para o transporte e a recolocação segura do seu mobiliário. A nossa equipa de operadores experientes trata do embalamento cuidadoso, carregamento, transporte e descarregamento eficiente na sua nova morada, recorrendo a veículos e ferramentas especializadas. Oferecemos tarifas horárias claras e transparentes de acordo com o pessoal necessário, garantindo eficiência. O seguro de transporte está incluído para todos os itens.',
    'services.movingFurniture.cta': 'Mudança Fácil',

    // Specialized Services
    'services.car.title': 'Estética Automotiva',
    'services.car.subtitle': 'Spa Móvel Profissional (Limpeza a Seco)',
    'services.car.marketingDesc': 'Mime o seu veículo com uma experiência de spa premium sem sair de casa. O nosso serviço móvel de estética automóvel inclui técnicas profissionais de limpeza a seco, proporcionando uma limpeza profunda de interiores topo de gama e restauro exterior com produtos ecológicos, sem água e biodegradáveis, certificados pela B Corp. Da remoção de manchas e tratamento Alcantara à proteção cerâmica, garantimos que o seu carro fica como novo com o mínimo impacto ambiental. Somos especialistas em tecnologias sem água para um serviço sem complicações em Zurique e Schaffhausen.',

    'services.gardening.title': 'Jardinagem de Precisão',
    'services.gardening.desc': 'Manutenção especializada do jardim, cuidado com relva e paisagismo em todas as estações.',
    'services.gardening.marketingDesc': 'A nossa equipa de jardinagem combina conhecimentos hortícolas com ferramentas de precisão para transformar e cuidar dos seus espaços verdes exteriores. Desde a plantação sazonal à poda precisa de sebes, até à fertilização biológica e reconstrução da relva. Focamo-nos na biodiversidade e irrigação otimizada em harmonia com o ecossistema suíço.',

    'services.exterior.title': 'Limpeza de Exteriores',
    'services.exterior.desc': 'Lavagem profissional a alta pressão e restauro de fachadas para exteriores como novos.',
    'services.exterior.marketingDesc': 'Preserve o valor estético e estrutural do seu imóvel com o nosso serviço técnico de limpeza profunda de exteriores. Usamos técnicas dedicadas de alta pressão e lavagem soft para materiais porosos ou delicados como pedra natural, betão, madeira e fachadas metálicas. Removemos musgos, fungos e poluição.',

    'services.pest.title': 'Controlo de Pragas',
    'services.pest.desc': 'Soluciones profissionais, seguras e discretas para todos os tipos de pragas.',
    'services.pest.marketingDesc': 'A Kraken disponibiliza intervenções ágeis e discretas para combate a pragas em escritórios ou habitações privadas. Optamos por estratégias modernas de baixo impacto que privilegiam barreiras mecânicas, ecológicas e monitorização preventiva, limitando o uso de químicos. Os nossos técnicos qualificados garantem higiene e conformidade com as exigências suíças.',

    'services.waste.title': 'Gestão e Recolha de Resíduos',
    'services.waste.desc': 'Sinalização e remoção ecológica de resíduos, desmontagem de móveis e reciclagem.',
    'services.waste.marketingDesc': 'Tornamos simples e limpa a remoção de resíduos ou desocupação de garagens e escritórios. A nossa equipa assegura a correta separação ecológica de recicláveis, móveis volumosos e resíduos eletrónicos (REEE/WEEE). Encaminhamos cada transporte para centros suíços regionais aprovados para o máximo respeito ecológico.',

    'services.gutter.title': 'Limpeza de Algerozes',
    'services.gutter.desc': 'Manutenção preventiva essencial para garantir a correta drenagem e prevenir infiltrações.',
    'services.gutter.marketingDesc': 'Algerozes e canos entupidos provocam graves danos estruturais nas paredes e fundações. O nosso serviço profissional remove com segurança folhas, musgos e terras recorrendo a aspiradores telescópicos de elevado alcance e câmaras de diagnóstico, prevenindo infiltrações antes das grandes chuvas na Suíça.',

