    // Navigation and Blog Keys
    'nav.blog': 'Blog',
    'blog.title': 'O Pulso da Ordem',
    'blog.subtitle': 'Perspetivas de especialistas em gestão de instalações, regras de entrega de apartamentos e otimização logística na Suíça.',
    'blog.readMore': 'Ler Artigo',
    'blog.backToBlog': 'Voltar ao Blog',
    'blog.published': 'Publicado em',
    'blog.author': 'Autor',
    'blog.readTime': 'Tempo de leitura',

    'blog.art1.title': 'Limpeza de Fim de Contrato em Zurique: Guia para a Entrega do Imóvel',
    'blog.art1.excerpt': 'Superar a inspeção de entrega de um imóvel na Suíça é notoriamente difícil. Conheça as normas rigorosas de limpeza e regras legais para recuperar a totalidade da sua caução.',
    'blog.art1.category': 'Manutenção Residencial',
    'blog.art1.p1': 'Mudar de casa na Suíça envolve uma etapa complexa e exigente: a inspeção e entrega do apartamento (Wohnungsabgabe). Na Suíça, os imóveis arrendados devem ser devolvidos num estado irrepreensível, muito acima dos padrões comuns. Senhorios e agências inspecionam cada milímetro sob rigorosa observação.',
    'blog.art1.p2': 'Os pontos onde ocorrem mais falhas incluem a cal acumulada nas misturadoras, filtros de exaustor engordurados e arrecadações ou caves (Keller) por limpar. Contratar um serviço como a Kraken, que oferece "Garantia de Entrega", assegura que a nossa equipa estará presente para corrigir qualquer pormenor apontado pelo inspetor.',
    'blog.art1.p3': 'Para limpar por conta própria, prepare uma lista estrita: remova o calcário das zonas húmidas com produtos industriais, limpe vidros e caixilharia de ambos os lados, limpe as persianas exteriores (Storen), aspire as carpetes e elimine riscos nas portas de madeira. Uma boa preparação poupa milhares de francos e evita dores de cabeça.',

    'blog.art2.title': 'Manutenção Solar nos Alpes: Maximização do Rendimento',
    'blog.art2.excerpt': 'Os painéis solares na Suíça enfrentam forte polinização de montanha, poeiras e fuligem de inverno. Saiba por que a lavagem profissional com água pura é essencial.',
    'blog.art2.category': 'Sustentabilidade',
    'blog.art2.p1': 'A Suíça é líder na integração de fontes limpas, com milhares de coberturas fotovoltaicas de Schaffhausen aos vales alpinos. Mas muitos proprietários desconhecem que poeiras Sahara, poluição e polen reduzem a produtividade energética em até 20% numa só estação. A chuva normal raras vezes remove esta película gordurosa.',
    'blog.art2.p2': 'A limpeza de painéis solares é um procedimento técnico sensível. A água comum deixa depósitos de calcário que criam micro-sombras e danificam as células solares por sobreaquecimento. A lavagem profissional exige água desmineralizada pura e escovas telescópicas rotativas muito suaves, sem exercer carga de peso nas placas.',
    'blog.art2.p3': 'A manutenção solar programada, feita idealmente na primavera a seguir ao polen e no outono antes das primeiras neves, valoriza o investimento imobiliário e garante a produção máxima de eletricidade amiga do ambiente.',

    'blog.art3.title': 'IoT e Smart Facility Offices: O Futuro dos Escritórios Suíços',
    'blog.art3.excerpt': 'Como sensores ambientais IoT, planeamento preditivo e relatórios unificados estão a otimizar o conforto dos colaboradores e o consumo energético corporativo.',
    'blog.art3.category': 'Inovação',
    'blog.art3.p1': 'A infraestrutura corporativa em centros urbanos como Zurique, Winterthur e Genebra está a viver uma transformação digital profunda. As limpezas diárias tradicionais utilizam calendários e tabelas fixas. Atualmente, os edifícios inteligentes recorrem a sensores IoT ativos para desencadear limpezas com base no uso real.',
    'blog.art3.p2': 'Ao monitorizar a ocupação de salas de reunião, a qualidade do ar e o tráfego nos sanitários, as equipas de limpeza e manutenção concentram-se no que é necessário. Se um auditório se manteve desocupado, os recursos são orientados para zonas de convívio e escritórios em uso ativo.',
    'blog.art3.p3': 'Esta gestão inteligente permite aos clientes B2B avaliar detalhadamente os indicadores energéticos, gerir tempos de resposta técnica e diminuir a pegada ecológica corporativa. A gestão conectada estabelece os padrões modernos de produtividade imobiliária.',

