export type Language = 'en' | 'de-CH' | 'de' | 'fr' | 'it' | 'es' | 'pt';

export const translations: Record<Language, Record<string, string>> = {
  'en': enTranslations,
  'de-CH': deTranslations,
  'de': deTranslations,
  'fr': frTranslations,
  'it': itTranslations,
  'es': esTranslations,
  'pt': ptTranslations,
};

interface I18nContextType {
  language: Language;
  setLanguage: (lang: Language) => void;
  t: (key: string, params?: Record<string, string | number>) => string;
}

const I18nContext = createContext<I18nContextType | undefined>(undefined);

export const I18nProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [language, setLanguageState] = useState<Language>('de-CH');

  const [activeToast, setActiveToast] = useState<{ show: boolean; msg: string; langCode: string } | null>(null);

  useEffect(() => {
    try {
      let detectedLang: Language | null = null;
      // 1. Check URL parameters for explicit language overrides (e.g. ?lang=fr or ?hl=es)
      if (typeof window !== 'undefined' && window.location) {
        const params = new URLSearchParams(window.location.search);
        const urlLang = params.get('lang') || params.get('hl');
        if (urlLang) {
          const matched = ['en', 'de-CH', 'de', 'fr', 'it', 'es', 'pt'].find(
            (l) => l.toLowerCase() === urlLang.toLowerCase() || l.split('-')[0].toLowerCase() === urlLang.toLowerCase()
          );
          if (matched) detectedLang = matched as Language;
        }
      }

      // 2. Check localStorage for user persistent language selection
      if (!detectedLang) {
        const saved = localStorage.getItem('kraken_preferred_lang');
        if (saved && ['en', 'de-CH', 'de', 'fr', 'it', 'es', 'pt'].includes(saved)) {
          detectedLang = saved as Language;
        }
      }

      // 3. Fallback to browser standard language setting (ONLY if it matches a German locale)
      if (!detectedLang && typeof navigator !== 'undefined' && navigator.language) {
        const browserFullLang = navigator.language.toLowerCase();
        if (browserFullLang === 'de-ch') {
          detectedLang = 'de-CH';
        } else {
          const browserLang = navigator.language.substring(0, 2).toLowerCase();
          if (browserLang === 'de') {
            detectedLang = 'de';
          }
        }
      }

      if (detectedLang && detectedLang !== 'de-CH') {
        setLanguageState(detectedLang);
      }
    } catch (e) {
      console.error('Failed to load language from localStorage / environments', e);
    }
  }, []);

  useEffect(() => {
    if (activeToast && activeToast.show) {
      const timer = setTimeout(() => {
        setActiveToast(prev => prev ? { ...prev, show: false } : null);
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [activeToast]);

  const langTitles: Record<Language, string> = {
    'en': 'Language Changed',
    'de-CH': 'Sprache angepasst',
    'de': 'Sprache angepasst',
    'fr': 'Langue modifiée',
    'it': 'Lingua modificata',
    'es': 'Idioma cambiado',
    'pt': 'Idioma alterado',
  };

  const setLanguage = (lang: Language) => {
    setLanguageState(lang);
    try {
      localStorage.setItem('kraken_preferred_lang', lang);
    } catch (e) {
      console.error('Failed to save language to localStorage', e);
    }

    const langNames: Record<Language, string> = {
      'en': 'English',
      'de-CH': 'Schweizerdeutsch',
      'de': 'Deutsch',
      'fr': 'Français',
      'it': 'Italiano',
      'es': 'Español',
      'pt': 'Português',
    };

    const confirmations: Record<Language, string> = {
      'en': 'Content updated to English',
      'de-CH': 'Inhalt auf Schweizerdeutsch aktualisiert',
      'de': 'Inhalt auf Deutsch aktualisiert',
      'fr': 'Contenu mis à jour en français',
      'it': 'Contenuto aggiornato in italiano',
      'es': 'Contenido actualizado a español',
      'pt': 'Conteúdo atualizado para português',
    };

    setActiveToast({
      show: true,
      msg: confirmations[lang] || `Language updated`,
      langCode: langNames[lang] || lang
    });
  };

  // Keep the <html lang> attribute in sync with the active language for SEO & accessibility
  useEffect(() => {
    if (typeof document !== 'undefined') {
      const htmlLangMap: Record<Language, string> = {
        'de-CH': 'de',
        'de': 'de',
        'en': 'en',
        'fr': 'fr',
        'it': 'it',
        'es': 'es',
        'pt': 'pt',
      };
      document.documentElement.lang = htmlLangMap[language] || 'de';
    }
  }, [language]);

  const t = (key: string, params?: Record<string, string | number>): string => {
    const langTranslations = translations[language] || translations['de'];
    let text = langTranslations[key] || translations['de'][key] || key;
    
    if (params) {
      Object.entries(params).forEach(([param, value]) => {
        text = text.replace(`{${param}}`, String(value));
      });
    }
    return text;
  };

  return (
    <I18nContext.Provider value={{ language, setLanguage, t }}>
      {children}
      {activeToast && activeToast.show && (
        <div
          key={`${activeToast.langCode}-${activeToast.msg}`}
          id="language-toast-notification"
          className="fixed top-24 right-5 sm:right-6 md:right-8 z-[200] max-w-sm w-[calc(100vw-2.5rem)] bg-white/95 backdrop-blur-md border border-gray-100 rounded-2xl shadow-[0_15px_35px_rgba(0,0,0,0.12)] p-4 flex items-center gap-3.5 pointer-events-auto transition-all duration-300 animate-toast-slide"
        >
          {/* Circular globe icon */}
          <div className="w-10 h-10 rounded-full bg-[#002D5B]/5 flex items-center justify-center shrink-0 text-base">
            🌐
          </div>
          
          {/* Content */}
          <div className="flex-1 text-left min-w-0">
            <h4 className="text-xs font-black text-[#002D5B] uppercase tracking-widest leading-none mb-1">
              {langTitles[language]}
            </h4>
            <p className="text-xs text-gray-500 font-medium leading-tight truncate">
              {activeToast.msg}
            </p>
          </div>

          {/* Close button */}
          <button
            onClick={() => setActiveToast(prev => prev ? { ...prev, show: false } : null)}
            className="text-gray-400 hover:text-gray-600 p-1 rounded-full hover:bg-gray-50 transition-colors"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>
      )}
      <style>{`
        @keyframes toast-slide {
          0% {
            opacity: 0;
            transform: translateY(-1rem) scale(0.95);
          }
          100% {
            opacity: 1;
            transform: translateY(0) scale(1);
          }
        }
        .animate-toast-slide {
          animation: toast-slide 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards;
        }
      `}</style>
    </I18nContext.Provider>
  );
};

export const useTranslation = () => {
  const context = useContext(I18nContext);
  if (!context) {
    throw new Error('useTranslation must be used within an I18nProvider');
  }
  return context;
};
